import { type Folder, type File, type ShareLink } from "wasp/entities";
import type { GetFolderContents, GetFolderBreadcrumbs, GetAccessLogs, GetShareLink, GetPublicShareLinkInfo } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getFolderContents: GetFolderContents<{ folderId?: string }, { folders: Folder[], files: File[], currentFolder: Folder | null }> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  let currentFolder: Folder | null = null;
  if (args.folderId) {
    currentFolder = await context.entities.Folder.findFirst({
      where: { id: args.folderId, userId },
    });
    if (!currentFolder) {
      throw new HttpError(404, "Folder not found");
    }
  }

  const folders = await context.entities.Folder.findMany({
    where: { parentId: args.folderId || null, userId },
    orderBy: { name: "asc" },
  });

  const files = await context.entities.File.findMany({
    where: { folderId: args.folderId || null, userId },
    orderBy: { name: "asc" },
  });

  return { folders, files, currentFolder };
};

export const getFolderBreadcrumbs: GetFolderBreadcrumbs<{ folderId?: string }, Folder[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  if (!args.folderId) {
    return [];
  }

  const crumbs: Folder[] = [];
  let currentId: string | null = args.folderId;

  while (currentId) {
    const folder = await context.entities.Folder.findFirst({
      where: { id: currentId, userId },
    });
    if (!folder) {
      break;
    }
    crumbs.unshift(folder);
    currentId = folder.parentId;
  }

  return crumbs;
};

export const getAccessLogs: GetAccessLogs<{}, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const logs = await context.entities.AccessLog.findMany({
    where: {
      file: {
        userId,
      },
    },
    include: {
      file: true,
    },
    orderBy: {
      timestamp: "desc",
    },
  });

  return logs;
};

export const getShareLink: GetShareLink<{ fileId: string }, ShareLink | null> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  // Ensure the file belongs to the user
  const file = await context.entities.File.findFirst({
    where: { id: args.fileId, userId },
  });
  if (!file) {
    throw new HttpError(404, "File not found");
  }

  const shareLink = await context.entities.ShareLink.findFirst({
    where: { fileId: args.fileId },
    orderBy: { createdAt: "desc" },
  });

  return shareLink;
};

export const getPublicShareLinkInfo: GetPublicShareLinkInfo<{ linkId: string }, { exists: boolean, isPasswordProtected: boolean, isExpired: boolean, fileName?: string, size?: number }> = async (args, context) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: { file: true },
  });

  if (!shareLink) {
    return { exists: false, isPasswordProtected: false, isExpired: false };
  }

  const isExpired = shareLink.expiresAt ? new Date() > shareLink.expiresAt : false;

  return {
    exists: true,
    isPasswordProtected: !!shareLink.password,
    isExpired,
    fileName: shareLink.file.name,
    size: shareLink.file.size,
  };
};

import type { CreateFolder, CreateShareLink } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const createFolder: CreateFolder<{ name: string, parentId?: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  // If parentId is specified, ensure it exists and belongs to the user
  if (args.parentId) {
    const parent = await context.entities.Folder.findFirst({
      where: { id: args.parentId, userId },
    });
    if (!parent) {
      throw new HttpError(404, "Parent folder not found");
    }
  }

  const folder = await context.entities.Folder.create({
    data: {
      name: args.name,
      parentId: args.parentId || null,
      userId,
    },
  });

  return folder;
};

export const createShareLink: CreateShareLink<{ fileId: string, password?: string, expiresAt?: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const file = await context.entities.File.findFirst({
    where: { id: args.fileId, userId },
  });
  if (!file) {
    throw new HttpError(404, "File not found");
  }

  // Delete existing share link if any (or we can just have one share link per file)
  await context.entities.ShareLink.deleteMany({
    where: { fileId: args.fileId },
  });

  const shareLink = await context.entities.ShareLink.create({
    data: {
      fileId: args.fileId,
      password: args.password || null,
      expiresAt: args.expiresAt ? new Date(args.expiresAt) : null,
    },
  });

  return shareLink;
};

import multer from "multer";
import fs from "fs";
import path from "path";

const uploadDir = "/home/user/app/uploads/";
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
    const ext = path.extname(file.originalname);
    cb(null, file.fieldname + "-" + uniqueSuffix + ext);
  },
});

const upload = multer({ storage });
const singleUpload = upload.single("file");

export const uploadFile = (req: any, res: any, context: any) => {
  if (!context.user) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  const userId = context.user.id;

  singleUpload(req, res, async (err) => {
    if (err) {
      return res.status(500).json({ error: err.message });
    }

    if (!req.file) {
      return res.status(400).json({ error: "No file uploaded" });
    }

    const { folderId } = req.body;

    try {
      if (folderId && folderId !== "null" && folderId !== "undefined") {
        const folder = await context.entities.Folder.findFirst({
          where: { id: folderId, userId },
        });
        if (!folder) {
          fs.unlinkSync(req.file.path);
          return res.status(404).json({ error: "Folder not found" });
        }
      }

      const fileRecord = await context.entities.File.create({
        data: {
          name: req.file.originalname,
          size: req.file.size,
          mimeType: req.file.mimetype,
          localPath: req.file.path,
          folderId: (folderId && folderId !== "null" && folderId !== "undefined") ? folderId : null,
          userId,
        },
      });

      return res.status(200).json(fileRecord);
    } catch (dbErr: any) {
      if (fs.existsSync(req.file.path)) {
        fs.unlinkSync(req.file.path);
      }
      return res.status(500).json({ error: dbErr.message });
    }
  });
};

export const downloadFile = async (req: any, res: any, context: any) => {
  const { linkId } = req.params;
  const { password } = req.query;

  try {
    const shareLink = await context.entities.ShareLink.findUnique({
      where: { id: linkId },
      include: { file: true },
    });

    if (!shareLink) {
      return res.status(404).json({ error: "Share link not found" });
    }

    if (shareLink.expiresAt && new Date() > shareLink.expiresAt) {
      return res.status(410).json({ error: "Share link has expired" });
    }

    if (shareLink.password && shareLink.password !== password) {
      return res.status(403).json({ error: "Incorrect password" });
    }

    const file = shareLink.file;
    if (!fs.existsSync(file.localPath)) {
      return res.status(404).json({ error: "File not found on server" });
    }

    const ipAddress = (req.headers['x-forwarded-for'] as string || req.ip || req.socket.remoteAddress || "Unknown").split(',')[0].trim();
    const userAgent = req.headers['user-agent'] || "Unknown";

    await context.entities.AccessLog.create({
      data: {
        fileId: file.id,
        ipAddress,
        userAgent,
      },
    });

    res.setHeader("Content-Type", file.mimeType);
    res.setHeader("Content-Disposition", `attachment; filename="${encodeURIComponent(file.name)}"`);
    res.setHeader("Content-Length", file.size);

    const fileStream = fs.createReadStream(file.localPath);
    fileStream.pipe(res);
  } catch (err: any) {
    return res.status(500).json({ error: err.message });
  }
};

